import 'package:janseva/config/api_config.dart';

class EsignRequest {
  final DocumentModel document;
  final List<Signer> signers;
  final bool estampRequired;
  final String? estampId;
  final String? estampVersion;
  final String? txnExpiryMin;
  final String? whiteLabel;
  final String? responseUrl;
  final String? esignType;
  final EmailTemplate? emailTemplate;

  EsignRequest({
    required this.document,
    required this.signers,
    this.estampRequired = true,
    this.estampId,
    this.estampVersion = "v2",
    this.txnExpiryMin = "10080",
    this.whiteLabel = "Y",
    this.responseUrl,
    this.esignType = "AADHAAR",
    this.emailTemplate,
  });

  Map<String, dynamic> toJson(String loanId) => {
    'document': document.toJson(),
    'signers': signers.map((e) => e.toJson()).toList(),
    'estamp_required': estampRequired,
    'estamp_id': estampId,
    'estamp_version': estampVersion,
    'txn_expiry_min': txnExpiryMin,
    'white_label': whiteLabel,
    'response_url': 'http://34.100.148.226:4000/api/v1/esign/esign-status/$loanId',
    'redirect_url': 'http://34.100.148.226:4000/api/v1/esign/esign-status/$loanId',
    'esign_type': esignType,
    'email_template': emailTemplate?.toJson(),
  };

  //copy with
  EsignRequest copyWith({
    DocumentModel? document,
    List<Signer>? signers,
    bool? estampRequired,
    String? estampId,
    String? estampVersion,
    String? txnExpiryMin,
    String? whiteLabel,
    String? responseUrl,
    String? esignType,
    EmailTemplate? emailTemplate,
  }) {
    return EsignRequest(
      document: document ?? this.document,
      signers: signers ?? this.signers,
      estampRequired: estampRequired ?? this.estampRequired,
      estampId: estampId ?? this.estampId,
      estampVersion: estampVersion ?? this.estampVersion,
      txnExpiryMin: txnExpiryMin ?? this.txnExpiryMin,
      whiteLabel: whiteLabel ?? this.whiteLabel,
      responseUrl: responseUrl ?? this.responseUrl,
      esignType: esignType ?? this.esignType,
      emailTemplate: emailTemplate ?? this.emailTemplate,
    );
  }
}

class DocumentModel {
  final String name;
  final String? info;
  final String? data; // base64 or raw string depending on how you use it

  DocumentModel({required this.name, this.info = "AGREEMET", this.data});

  Map<String, dynamic> toJson() => {'name': name, 'info': info, 'data': data};
}

class Signer {
  final String signerName;
  final String signerEmail;
  final String? signerCity;
  final String? signerPurpose;
  final List<SignCoordinate> signCoordinates;

  Signer({
    required this.signerName,
    required this.signerEmail,
    this.signerCity,
    this.signerPurpose,
    required this.signCoordinates,
  });

  Map<String, dynamic> toJson() => {
    'signer_name': signerName,
    'signer_email': signerEmail,
    'signer_city': signerCity,
    'signer_purpose': signerPurpose,
    'sign_coordinates': signCoordinates.map((e) => e.toJson()).toList(),
  };
}

class SignCoordinate {
  final int pageNum;
  final num xCoord;
  final num yCoord;

  SignCoordinate({required this.pageNum, this.xCoord = 0, this.yCoord = 0});

  Map<String, dynamic> toJson() => {
    'page_num': pageNum,
    'x_coord': xCoord,
    'y_coord': yCoord,
  };
}

class EmailTemplate {
  final String? orgName;

  EmailTemplate({this.orgName});

  Map<String, dynamic> toJson() => {'org_name': orgName ?? "NEXTLABS"};
}

